TLM.f("Tempora/Quad3-0",{"officium":"Dominica III in Quadragesima","rule":["no Gloria","Credo","Prefatio=Quad","Suffragium=Sanctorum;Vivis;;"],"sections":{"Introitus":[{"k":"ref","la":"Ps 24:15-16"},{"k":"text","la":"Oculi mei semper ad Dóminum, quia ipse evéllet de láqueo pedes meos: réspice in me, et miserére mei, quóniam únicus et pauper sum ego."},{"k":"ref","la":"Ps 24:1-2"},{"k":"text","la":"Ad te, Dómine, levávi ánimam meam: Deus meus, in te confído, non erubéscam,"},{"k":"macro","name":"Gloria"},{"k":"text","la":"Oculi mei semper ad Dóminum, quia ipse evéllet de láqueo pedes meos: réspice in me, et miserére mei, quóniam únicus et pauper sum ego."}],"Oratio":[{"k":"text","la":"Quǽsumus, omnípotens Deus, vota humílium réspice: atque, ad defensiónem nostram, déxteram tuæ majestátis exténde."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Ephésios."},{"k":"ref","la":"Ephes 5:1-9"},{"k":"text","la":"Fratres: Estóte imitatóres Dei, sicut fílii caríssimi: et ambuláte in dilectióne, sicut et Christus diléxit nos, et trádidit semetípsum pro nobis oblatiónem, et hóstiam Deo in odórem suavitátis. Fornicátio autem et omnis immundítia aut avarítia nec nominétur in vobis, sicut decet sanctos: aut turpitúdo aut stultilóquium aut scurrílitas, quæ ad rem non pértinet: sed magis gratiárum áctio. Hoc enim scitóte intelligéntes, quod omnis fornicátor aut immúndus aut ávarus, quod est idolórum sérvitus, non habet hereditátem in regno Christi et Dei. Nemo vos sedúcat inánibus verbis: propter hæc enim venit ira Dei in fílios diffidéntiæ. Nolíte ergo éffici partícipes eórum. Erátis enim aliquándo ténebræ: nunc autem lux in Dómino. Ut fílii lucis ambuláte: fructus enim lucis est in omni bonitáte et justítia et veritáte."}],"Graduale":[{"k":"ref","la":"Ps 9:20; 9:4"},{"k":"text","la":"Exsúrge, Dómine, non præváleat homo: judicéntur gentes in conspéctu tuo."},{"k":"text","la":"In converténdo inimícum meum retrórsum, infirmabúntur, et períbunt a facie tua.","mark":"V"},{"k":"sep"},{"k":"rubric","la":"Tractus"},{"k":"ref","la":"Ps 122:1-3"},{"k":"text","la":"Ad te levávi óculos meos, qui hábitas in cœlis."},{"k":"text","la":"Ecce, sicut óculi servórum in mánibus dominórum suórum.","mark":"V"},{"k":"text","la":"Et sicut óculi ancíllæ in mánibus dóminæ suæ: ita óculi nostri ad Dóminum, Deum nostrum, donec misereátur nostri,","mark":"V"},{"k":"text","la":"Miserére nobis, Dómine, miserére nobis.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam."},{"k":"ref","la":"Luc 11:14-28"},{"k":"text","la":"In illo témpore: Erat Jesus ejíciens dæmónium, et illud erat mutum. Et cum ejecísset dæmónium, locútus est mutus, et admirátæ sunt turbæ. Quidam autem ex eis dixérunt: In Beélzebub, príncipe dæmoniórum, éjicit dæmónia. Et álii tentántes, signum de cœlo quærébant ab eo. Ipse autem ut vidit cogitatiónes eórum, dixit eis: Omne regnum in seípsum divísum desolábitur, et domus supra domum cadet. Si autem et sátanas in seípsum divísus est, quómodo stabit regnum ejus? quia dícitis, in Beélzebub me ejícere dæmónia. Si autem ego in Beélzebub ejício dæmónia: fílii vestri in quo ejíciunt? Ideo ipsi júdices vestri erunt. Porro si in dígito Dei ejício dæmónia: profécto pervénit in vos regnum Dei. Cum fortis armátus custódit átrium suum, in pace sunt ea, quæ póssidet. Si autem fórtior eo supervéniens vícerit eum, univérsa arma ejus áuferet, in quibus confidébat, et spólia ejus distríbuet. Qui non est mecum, contra me est: et qui non cólligit mecum, dispérgit. Cum immúndus spíritus exíerit de hómine, ámbulat per loca inaquósa, quærens réquiem: et non invéniens, dicit: Revértar in domum meam, unde exívi. Et cum vénerit, invénit eam scopis mundátam, et ornátam. Tunc vadit, et assúmit septem álios spíritus secum nequióres se, et ingréssi hábitant ibi. Et fiunt novíssima hóminis illíus pejóra prióribus. Factum est autem, cum hæc díceret: extóllens vocem quædam múlier de turba, dixit illi: Beátus venter, qui te portávit, et úbera, quæ suxísti. At ille dixit: Quinímmo beáti, qui áudiunt verbum Dei, et custódiunt illud."}],"Offertorium":[{"k":"ref","la":"Ps 18:9, 10, 11, 12"},{"k":"text","la":"Justítiæ Dómini rectæ, lætificántes corda, et judícia ejus dulcióra super mel et favum: nam et servus tuus custódit ea."}],"Secreta":[{"k":"text","la":"Hæc hóstia, Dómine, quǽsumus, emúndet nostra delícta: et, ad sacrifícium celebrándum, subditórum tibi córpora mentésque sanctíficet."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 83:4-5"},{"k":"text","la":"Passer invénit sibi domum, et turtur nidum, ubi repónat pullos suos: altária tua, Dómine virtútum, Rex meus, et Deus meus: beáti, qui hábitant in domo tua, in sǽculum sǽculi laudábunt te."}],"Postcommunio":[{"k":"text","la":"A cunctis nos, quǽsumus, Dómine, reátibus et perículis propitiátus absólve: quos tanti mystérii tríbuis esse partícipes."},{"k":"macro","name":"Per Dominum"}]},"hr":{"41b0165e50c60c92":{"t":"Ps 24, 15-16, Ps 24, 1-2\n(Ps 24, 15-16) Moje su oči uvijek upravljene prema Gospodinu, jer on izbavlja moje noge iz zamke. Pogledaj na me i smiluj mi se jer sam osamljen i bijedan. (Ps 24, 1-2) K tebi, Gospodine, uzdižem svoju dušu, u tebe se uzdam. Ne daj da se postidim.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 24, 15-16) Moje su oči uvijek upravljene prema Gospodinu, jer on izbavlja moje noge iz zamke. Pogledaj na me i smiluj mi se jer sam osamljen i bijedan.","kn":"(Ps. 24, 15, 16). Oči su moje uvijek upravljene Gosipodinu, jer on vadi iz zamke noge moje. Pogledaj me i smiluj se meni, jer sam osamljen i ubog! (Ps^ 24, 1, 2). K Tebi, Gospodine, dižem dušu svoju, Bože moj. u Te se ufam i ,ne ču se zasitidjeti! Slava Ocu... Oči su moje...","knRef":"Kniewald 1942, str. 150–151 (snimka 76) (OCR)"},"df21dd20fa8e64b9":{"t":"<i>Pomolimo se</i>.\nPogledaj, molimo, svemogući Bože, na molitve poniznih i u našu obranu pruži desnicu svojeg veličanstva.","kn":"Obazri se. molimo. Gospodine, na prošnje poniznih i pruži desnicu svoga veličanstva na obranu našu, ipo G. n.","knRef":"Kniewald 1942, str. 150–151 (snimka 76) (OCR)"},"9cc343eec883de83":{"t":"Ef 5, 1-9\nČitanje Poslanice bl. Pavla apostola Efežanima. Braćo: nasljedujte Boga kao predraga djeca i ljubite se kao što je Krist ljubio nas i za nas se predao kao prinos i miomirisna žrtva Bogu. A bludnost ili kakva druga nečistoća i škrtost neka se među vama i ne spominje, kao što dolikuje svetima. Tako ni bestidnost i besmislen govor ili nepristojne šale, što sve nije na mjestu, nego radije zahvaljivanje. Znajte ovo i dobro zapamtite: nijedan bludnik ili nečist čovjek ili škrtac, jer su to idolopoklonici, neće imati baštine u Kristovu i Božjem kraljevstvu. Da vas ne bi tko zavarao ispraznim riječima, jer zbog toga dolazi Božja srdžba na nepokornu djecu. Dakle, ne budite njihovi sudrugovi! Nekada ste bili tama, ali sada ste svjetlo u Gospodinu. Živite kao djeca svjetla, jer plod je svjetla dobrota, pravda i istina.","kn":"Čitanje poslanice bi. Pavla apostola Efežanima (5) 1-9). Braćo! Ugledajte se u Boga kao predraga djeca i ljubite se, kao što je i Krist nas ljubio i sebe predao za nas kao prinos i žrtvu Bogu na siadak miomiris. A bludnosti niti kakve nečistoće i škrtosti meka se među vama ni ne spominju, kao što dolikuje svetima; tako ni bestiidnostl ni ludog govora ili nepristojne šale, što ne dolikuje, nego radije zahvaljivanje. Jer znajte ovo 1 razumijte- Nijedan bludnik ili nečistnik ili škrtac, što je idolopoklonstvo, ne će imati baštine u Kristovu i Božjem kraljevstvu. Neka vas nitko ne zavodi ispraznim riječima, jer radi toga dolazi Božja srdžba na nepokornu djecu. Nemojte dakle s njima sudjelovati! Jer ste nekada bili tama, a sada ste svjetlost u Gospodinu. Živite kao djeca svjetlosti, jer plod svjetlosti je svaka dobrota i pravda i istina.","knRef":"Kniewald 1942, str. 150–151 (snimka 76) (OCR)"},"2ca20d4198095b83":{"t":"Ps 20, 9 et 4\nUstani, Gospodine, da se ne osili čovjek! Neka narodi budu suđeni pred tvojim licem. Nagnao si moje neprijatelje u bijeg, te klonuše i izgiboše pred tvojim licem.\n\nPs 122, 1-3\nPodižem svoje oči k tebi koji stanuješ na nebesima. Gle, kao što su oči slugu uprte u ruke njihovih gospodara, kao što su oči sluškinje uprte u ruke njezine gospodarice, tako su naše oči uprte u Gospodina, Boga našega, dok nam se ne smiluje. Smiluj nam se, Gospodine, smiluj nam se!","kn":"(Ps. 9, 20, 4). Ustani, Gospodine, da se ne ponese čovjek, bud-i sudac nad narodima! Ti si potisnuo moje neprijatelje, obnemogli su i poništeni su pred licem Tvojim. (Ps. 122, 1-3). K Tebi uzdižem oči svoje, koji stoluješ na nebesima. Evo, oči su naše upravljen na Gospodina Boga našega, kao oči slugu na gospodara i oči službenica na gospodaricu njihovu, dok im se ne smiluje. Smiluj nam se. Gospodine, smiluj nam se!","knRef":"Kniewald 1942, str. 150–151 (snimka 76) (OCR)"},"bb2dd66850ae1f50":{"t":"Lk 11, 14-28\nSlijedi sveto Evanđelje po Luki. U ono vrijeme: Isus je izgonio đavola iz čovjeka koji je bio nijem. I kad je istjerao đavla, nijemi progovori, i mnoštvo se ljudi divilo. Ali neki rekoše: On izgoni đavla pomoću Beelzebuba, poglavice đavola. Drugi pak iskušavajući ga zatraže od njega znak s neba. – Isus razumije njihove misli i reče: Svako kraljevstvo u sebi nesložno opustjet će, i srušit će se kuća na kuću. Tako, ako je i đavao zavađen u sebi, kako će se održati njegovo kraljevstvo? Kažete naime da ja izgonim đavla pomoću Beelzebuba. Ako ja izgonim đavla pomoću Beelzebuba, čijom ih moću izgone vaši sinovi? Zato će vam oni biti suci. Ali, ako đavla izgonim Božjom silom, doista je Božje kraljevstvo došlo k vama. Kada jak i dobro naoružan čovjek čuva svoj dom, u miru je sve što ima. Ali, kad dođe jači od njega i svlada ga, uzme mu oružje u koje se pouzdavao i razdijeli što zaplijeni. Tko nije sa mnom protiv mene je, i tko ne sabire sa mnom, rasipa. Kad nečisti duh izađe iz čovjeka, luta po pustim mjestima tražeći pokoja. Ali, kad ga ne nađe, reče: Povratit ću se u svoju kuću iz koje sam izišao. I kad se povrati, nađe je pometenu i uređenu. Zatim otiđe, uzme sa sobom sedam drugih duhova gorih od sebe, i s njima uniđe i nastani se ondje. Tako posljednje stanje onog čovjeka bude gore od pređašnjega – Kad je on to rekao, neka žena iz naroda poviče: Blago utrobi koja te nosila i prsima koje su te dojile! A on odgovori: Još više blago onima koji slušaju Božju riječ i po njoj žive.","kn":"t Slijedi sveto evanđelje po Luki (11, 14-28). U ono vrijeme izgonio je Isus đavla, koji je bio nijem, I kad istjera đavla, progovori nijemi, i divio se narod. A neki od njih reknu: On izgoni đavle po Belzebubu, đavolskom poglavici. A drugi kušajući ga zatraže od njega znak s neba. On, jer je razumio njihove misli, reče im; Svako kraljevstvo, koje je pocijepano u sebi, opustjet će i pasti će kuća na kuću. Ako je daikle i đavao u sebi zavađen, kako će se uzdržati njegovo kraljevstvo, kad kažete, da ja izgonim đavle po Belzebubu? Ako ja Izgonim đavle po Belzebubu, po ikomu ih izgone vaši sinovi? Zato će vam oni biti suci. Ali ako ja izgonim đavle Božjom jakošću, zaista je došlo k vama kraljevstvo Božje. Kad jaki naoružan čuva svoj. dvor, u miru je sve, što ima. A kad dođe jači od njega i nadvlada ga, uzme sve njegovo oružje, u koje se uzdao, i razdijeli njegov plijen. Tko nije sa mnom, protiv mene je, i prosiplje, tko ne sabire sa mnom. Kad nečisti duh izađe iz čovjeka, ide po pustim mjestima tražeći pokoja; ali kad ga ne nađe, reče: Vratit ću se u svoju kuću, odkuda sam izašao. I kad dođe, nađe je pometenu i nakićenu. Tada otiđe i uzme sa sobom sedam drugih duhova gorih od sebe, uniđu i naistane se ondje. I na koncu s tim čovjekom, bude gore nego na početku. Kad je on to govorio, reče mu glasno neka zetna iz naroda; Blago tijelu, koje te je nosilo i prsima, koja su te dojila. On na to odgovori: Još više blago onima, koji slušaju riječ Božju i drže je.","knRef":"Kniewald 1942, str. 150–151 (snimka 76) (OCR)"},"abdab28d88e9b4d3":{"t":"Ps 18, 9 i 10 i 11 i 12\nNaredbe su Gospodnje ispravne, one razveseljuju srca. I sudovi su njegovi slađi od meda i saća, pa sluga tvoj pazi na njih.","kn":"(Ps. 18, 9-12). Zapovijedi su Gospodnje pravedne, one Vesele srca, i sudovi njegovi šlađi -od međa i saća, zato ih i sluga Tvoj čuva.","knRef":"Kniewald 1942, str. 388–389 (snimka 195) (OCR)"},"fbb53f48d9c24f02":{"t":"Molimo, Gospodine, da ovaj žrtveni dar izbriše naša zlodjela te da dušu i tijelo tvojih podložnika posveti za svetkovanje žrtve.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo; Gospodine, da ovaj žrtveni dar očisti naše opačine i da posveti tijelo i dušu Tvojih slugu za svetkovanje žrtve, po G. n. I. K.","knRef":"Kniewald 1942, str. 98–99 (snimka 50) (OCR)"},"8e0447f4695d07e4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi Gospodine, sveti Oče, svemogući vječni Bože: – ti tjelesnim postom suzbijaš opačine, uzdižeš dušu, daješ krepost i nagrade po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo 1 spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože. koji tjelesnim postom obuzdavaš opačine, duh dižeš, daješ krepost i nagrade,' po Kristu, Gospodinu našemu; po kojem veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti, Nebesa Te 1 nebeske Red i čin sv. mise moći i blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se s njima smiju sjediniti i naši glasovi, koji govore u smjernom ispovijedanju:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"21f79a019b218ea8":{"t":"Ps 83, 4-5\nVrabac nalazi sebi dom i grlica gnijezdo gdje da stavi svoje mlade. Tako ja nalazim tvoje oltare, Gospodine nad vojskama. Kralju moj i Bože moj! Blažen koji stanuju u tvojem domu, Gospodine! Oni će te vječno slaviti.","kn":"(Ps. 83, 4, 5). I vrabac nalazi sebi kuću i grlica sebi gnijezdo, gdje stavlja ptiće svoje: a ja tražim oltare Tvoje, Gospodine nad vojskama. Kralju moj i Bože moj! Blago onima, koji prebivaju u^ kući Tvojoj, oni Te hvale u vijeke vjekova!","knRef":"Kniewald 1942, str. 152–153 (snimka 77) (OCR)"},"6fc5f17b5eaa9f0a":{"t":"<i>Pomolimo se</i>.\nOd svih krivica i pogibli milostivo oslobodi, molimo, Gospodine, nas kojima daješ da budemo dionici ovog velikog otajstva.","kn":"Molimo Te, Gospodine, koji nam darivaš, da budemo dionici tolikih tajna, oslobodi nas milostivo od svih grijeha i pogibli, po G. n.","knRef":"Kniewald 1942, str. 152–153 (snimka 77) (OCR)"}}});
